//         hints.base_height = terminal-&gt;char_height;
//         hints.min_width = terminal-&gt;char_width;
//         hints.min_height = terminal-&gt;char_height;
//         hints.width_inc = terminal-&gt;char_width;
//         hints.height_inc = terminal-&gt;char_height;
